<?php
require_once 'config/database.php';
$search=mb_substr(trim($_GET['search']??''),0,100);$category=trim($_GET['category']??'');
$sort=$_GET['sort']??'newest';$new=($_GET['new']??'')==='1';$featured=($_GET['featured']??'')==='1';$in_stock=($_GET['stock']??'')==='1';
$orders=['newest'=>'created_at DESC,id DESC','price_asc'=>'price ASC,id DESC','price_desc'=>'price DESC,id DESC','name'=>'name ASC,id DESC'];if(!isset($orders[$sort]))$sort='newest';
$where=['is_active=1'];$params=[];
if($search!=='') { $where[]='(name LIKE ? OR description LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%'; }
if($category!=='') { $where[]='category=?';$params[]=$category; }
if($new)$where[]='is_new=1';if($featured)$where[]='is_featured=1';if($in_stock)$where[]='stock>0';
$clause=implode(' AND ',$where);$total=(int)db_run('SELECT COUNT(*) total FROM products WHERE '.$clause,$params)->get_result()->fetch_assoc()['total'];
$per_page=max(2,min(48,(int)setting('per_page')));$pages=max(1,(int)ceil($total/$per_page));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*$per_page;
$products=db_run('SELECT * FROM products WHERE '.$clause.' ORDER BY '.$orders[$sort].' LIMIT ? OFFSET ?',array_merge($params,[$per_page,$offset]))->get_result()->fetch_all(MYSQLI_ASSOC);
$categories=$conn->query("SELECT DISTINCT category FROM products WHERE is_active=1 AND category<>'' ORDER BY category")->fetch_all(MYSQLI_ASSOC);
$page_title='Bộ sưu tập · '.setting('site_name');include 'includes/header.php';
?>
<section class="page-heading"><div class="container"><p class="eyebrow">VALISTORE / BỘ SƯU TẬP</p><h1><?= $new?'Hàng mới đến':($featured?'Sản phẩm nổi bật':'Mỗi chuyến đi, một lựa chọn.') ?></h1><p><?= e(setting('catalog_intro')) ?></p></div></section>
<div class="container catalog-page"><?php show_flash() ?><form method="get" class="catalog-filters" role="search"><div class="filter-search"><label for="search">Tìm sản phẩm</label><div><i aria-hidden="true" class="bi bi-search"></i><input type="search" id="search" name="search" maxlength="100" placeholder="Tên vali, balo, túi du lịch..." value="<?= e($search) ?>"></div></div><div><label for="category">Danh mục</label><select class="form-select" id="category" name="category"><option value="">Tất cả danh mục</option><?php foreach($categories as $cat): ?><option <?= $category===$cat['category']?'selected':'' ?>><?= e($cat['category']) ?></option><?php endforeach ?></select></div><div><label for="sort">Sắp xếp</label><select class="form-select" id="sort" name="sort"><?php foreach(['newest'=>'Mới nhất','price_asc'=>'Giá tăng dần','price_desc'=>'Giá giảm dần','name'=>'Tên A → Z'] as $v=>$label): ?><option value="<?= $v ?>" <?= $sort===$v?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><button class="btn btn-dark">Áp dụng</button><div class="filter-toggles"><label><input type="checkbox" name="new" value="1" <?= $new?'checked':'' ?>> Hàng mới</label><label><input type="checkbox" name="featured" value="1" <?= $featured?'checked':'' ?>> Nổi bật</label><label><input type="checkbox" name="stock" value="1" <?= $in_stock?'checked':'' ?>> Còn hàng</label><a href="catalog.php">Xóa bộ lọc</a></div></form>
<div class="catalog-toolbar"><span><?= $total ?> sản phẩm<?= $search!==''?' cho “'.e($search).'”':'' ?></span><span>Trang <?= $page ?> / <?= $pages ?></span></div>
<?php if($products): ?><div class="product-grid catalog-grid"><?php foreach($products as $p) product_card($p) ?></div><?php else: ?><div class="empty-state"><i aria-hidden="true" class="bi bi-search"></i><h2>Chưa tìm thấy hành trang phù hợp.</h2><p>Thử từ khóa khác hoặc xóa bộ lọc để xem thêm sản phẩm.</p><a class="btn btn-dark" href="catalog.php">Xem tất cả</a></div><?php endif ?>
<?php if($pages>1): ?><nav class="shop-pagination" aria-label="Phân trang sản phẩm"><?php $query=['search'=>$search,'category'=>$category,'sort'=>$sort,'new'=>$new?'1':'','featured'=>$featured?'1':'','stock'=>$in_stock?'1':''];if($page>1): ?><a href="?<?= e(http_build_query(array_merge($query,['page'=>$page-1]))) ?>" aria-label="Trang trước"><i aria-hidden="true" class="bi bi-arrow-left"></i></a><?php endif;for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++): ?><a href="?<?= e(http_build_query(array_merge($query,['page'=>$i]))) ?>" <?= $i===$page?'aria-current="page"':'' ?>><?= $i ?></a><?php endfor;if($page<$pages): ?><a href="?<?= e(http_build_query(array_merge($query,['page'=>$page+1]))) ?>" aria-label="Trang sau"><i aria-hidden="true" class="bi bi-arrow-right"></i></a><?php endif ?></nav><?php endif ?></div>
<?php include 'includes/footer.php' ?>
